values
  ('mae_lx_0vCBk_op', 'maestria', 'opcion_tablero', 1, 710, 876, 'Las negras acaban de jugar …Rf3. Juegan las blancas. Solo una de estas jugadas gana: ¿cuál?', '["Tf7+","Txg7","Tb1","Tb8"]'::jsonb, '8/1R4p1/7p/8/4r3/3K1kP1/8/8 w - - 11 67', 0, null, null, 'Es una desviación: se aleja al defensor de lo que defendía. La línea: 67.Tf7+ Rg4 68.Rxe4. Las otras tientan, pero fallan: Txg7? se contesta con 67…Te3+ y la ventaja se esfuma; Tb1? se contesta con 67…Tg4 y las negras quedan mejor; Tb8? se contesta con 67…Te6 y las negras quedan mejor.', '0vCBk', 1426),
  ('mae_lx_19wrU_op', 'maestria', 'opcion_tablero', 1, 840, 1002, 'Las negras acaban de jugar …Txg2. Juegan las blancas. Solo una de estas jugadas gana: ¿cuál?', '["Td1+","Tf5","Td6","Td7"]'::jsonb, '8/8/7p/3R4/4Pp2/5P1K/6r1/6k1 w - - 0 54', 0, null, null, ' La línea: 54.Td1+ Rf2 55.Td2+ Rxf3 56.Txg2. Las otras tientan, pero fallan: Tf5? se contesta con 54…Tg3+ y la ventaja se esfuma; Td6? se contesta con 54…Tg3+ y la ventaja se esfuma; Td7? se contesta con 54…Tg3+ y la ventaja se esfuma.', '19wrU', 1552),
  ('mae_lx_22L3m', 'maestria', 'jugada', 1, 190, 573, 'Las negras acaban de jugar …g5. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, '6k1/5p2/p1n2B1p/Pp2p1p1/1b2N3/8/1r3PPP/2R2K2 w - - 0 38', null, '{"from":"c1","to":"c6"}'::jsonb, null, 'Hay algo sin defender, y hay que verlo antes que el rival. La línea: 38.Txc6 Tb1+ 39.Re2.', '22L3m', 973),
  ('mae_lx_2USlI_op', 'maestria', 'opcion_tablero', 1, 910, 1078, 'Las negras acaban de jugar …Ag5. Juegan las blancas. Solo una de estas jugadas gana: ¿cuál?', '["Cxf5+","Cg4+","Th7+","Cf1"]'::jsonb, '3r4/pR6/6pk/5pb1/r7/4N1PK/P3RP2/8 w - - 1 36', 0, null, null, 'Es un despeje: la pieza se aparta para abrirle la línea o la casilla a otra. La línea: 36.Cxf5+ gxf5 37.Te6+. Las otras tientan, pero fallan: Cg4+? se contesta con 36…fxg4+ y las negras quedan mejor; Th7+? se contesta con 36…Rxh7 y las negras quedan mejor; Cf1? se contesta con 36…Tg8 y la ventaja se esfuma.', '2USlI', 1628),
  ('mae_lx_1kz0U', 'maestria', 'jugada', 2, 1120, 1192, 'Las negras acaban de jugar …Dd7. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, '1br2rk1/1p1q1ppp/p1n5/3p1N2/4nB2/2P3PP/PP3P2/RN1Q1RK1 w - - 3 16', null, '{"from":"d1","to":"g4"}'::jsonb, null, 'La línea: 16.Dg4 Dxf5 17.Dxf5.', '1kz0U', 1592),
